from __future__ import annotations

from dataclasses import dataclass

import numpy as np


BOHR_TO_ANGSTROM = 0.529177210903


@dataclass(frozen=True)
class GridField:
    values: np.ndarray
    weights: np.ndarray
    length_unit: str


@dataclass(frozen=True)
class PortableGrid:
    density: np.ndarray
    cell_weights: np.ndarray
    length_unit: str


def pack_grid_field(field: GridField) -> PortableGrid:
    volume_factor = BOHR_TO_ANGSTROM**3
    return PortableGrid(
        density=np.asarray(field.values / volume_factor),
        cell_weights=np.asarray(field.weights * volume_factor),
        length_unit="angstrom",
    )


def unpack_grid_field(payload: PortableGrid) -> GridField:
    if payload.length_unit != "angstrom":
        raise ValueError(f"Unsupported portable grid unit: {payload.length_unit}")
    return GridField(
        values=np.asarray(payload.density),
        weights=np.asarray(payload.cell_weights),
        length_unit=payload.length_unit,
    )


@lru_cache(maxsize=None)
def sample_grid_field(
    atom_spec: str,
    basis: str = DEFAULT_BASIS,
    grid_level: int = DEFAULT_GRID_LEVEL,
) -> GridField:
    mol, mf = run_pbe_density(atom_spec, basis=basis, grid_level=grid_level)
    grids = dft.gen_grid.Grids(mol)
    grids.level = grid_level
    grids.build()
    ao = numint.eval_ao(mol, grids.coords)
    dm = mf.make_rdm1()
    values = numint.eval_rho(mol, ao, dm, xctype="LDA")
    return GridField(
        values=np.asarray(values),
        weights=np.asarray(grids.weights),
        length_unit="bohr",
    )


def _integrated_field(field: GridField) -> float:
    value = float(np.dot(field.values, field.weights))
    if value <= 0.0:
        raise ValueError("Cannot evaluate an empty grid field")
    return value


def screening_parameter_from_field(field: GridField) -> float:
    total = _integrated_field(field)
    switch = erf(total * field.values / RHO_IN)
    mask = field.values > EPSILON
    integrand = np.zeros_like(field.values)
    integrand[mask] = (
        (3.0 / (4.0 * np.pi * field.values[mask])) ** (1.0 / 3.0)
        * switch[mask]
    )
    normalization = float(np.dot(switch, field.weights))
    if abs(normalization) < 1e-14:
        raise ZeroDivisionError("screening normalization vanished")
    avg_rs = float(np.dot(integrand, field.weights) / normalization)
    if field.length_unit == "angstrom":
        avg_rs /= BOHR_TO_ANGSTROM
    elif field.length_unit != "bohr":
        raise ValueError(f"Unsupported grid field unit: {field.length_unit}")
    return float(
        OMEGA_EFF_A1 / avg_rs
        + OMEGA_EFF_A2 * avg_rs / (1.0 + OMEGA_EFF_A3 * avg_rs**2)
    )


def _process_collection(
    systems: list[SystemRecord],
    basis: str,
    grid_level: int,
) -> list[SystemResult]:
    payloads = [
        pack_grid_field(sample_grid_field(system.atom_spec, basis=basis, grid_level=grid_level))
        for system in systems
    ]
    restored = [unpack_grid_field(payload) for payload in payloads]
    return [
        SystemResult(
            family=system.family,
            label=system.label,
            chain_index=system.chain_index,
            screening_parameter=screening_parameter_from_field(field),
        )
        for system, field in zip(systems, restored)
    ]


